INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DaaS dasselbe wie eine lokale Datenbank?', 2, '[{"text": "Nein", "correct": true, "because": "DaaS ist Cloud-basiert"}, {"text": "Ja", "correct": false, "because": "Lokale DBs sind On-Premise"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Vorteil bietet mir DaaS?', 3, '[{"text": "Skalierbarkeit", "correct": true, "because": "Ressourcen flexibel anpassbar"}, {"text": "Maximale Sicherheit", "correct": false, "because": "Sicherheit ist komplexer"}, {"text": "Kostenlose Nutzung", "correct": false, "because": "Abo-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien unterstützen DaaS?', 5, '[{"text": "APIs", "correct": true, "because": "Daten on-demand liefern"}, {"text": "Cloud-Speicher", "correct": true, "because": "Datenhaltung"}, {"text": "Grafiktreiber", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DaaS nutzt die Cloud. b) Es ersetzt lokale Server komplett.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lokale Server bleiben oft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der DaaS-Planung?', 4, '[{"text": "Datensicherheit", "correct": false, "because": "Kritischer Aspekt"}, {"text": "Skalierung", "correct": false, "because": "Kernvorteil"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DaaS immer teuer ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten variieren nach Anbieter"}, {"text": "Ja", "correct": false, "because": "Flexibel skalierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für DaaS typisch?', 3, '[{"text": "On-Demand-Zugriff", "correct": true, "because": "Kernprinzip"}, {"text": "Lokale Installation", "correct": false, "because": "Cloud-basiert"}, {"text": "Manuelle Updates", "correct": false, "because": "Automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche profitieren von DaaS?', 5, '[{"text": "Business Intelligence", "correct": true, "because": "Datenanalyse"}, {"text": "Datenintegration", "correct": true, "because": "Multi-Source-Zugriff"}, {"text": "Hardware-Wartung", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DaaS spart Speicherplatz. b) Es ist unsicher. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit abhängig von Maßnahmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DaaS?', 4, '[{"text": "Netzwerkverbindung", "correct": false, "because": "Zugang nötig"}, {"text": "Cloud-Provider", "correct": false, "because": "Hostet Daten"}, {"text": "Lokale Festplatte", "correct": true, "because": "Daten in Cloud"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DaaS dasselbe wie SaaS?', 2, '[{"text": "Nein", "correct": true, "because": "DaaS liefert Daten, SaaS Software"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Schwerpunkte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenquellen nutzt DaaS?', 4, '[{"text": "Interne Daten", "correct": true, "because": "Eigene Systeme"}, {"text": "Externe Daten", "correct": true, "because": "Drittanbieter"}, {"text": "Papierdokumente", "correct": false, "because": "Digital nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DaaS keine Wartung braucht. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Provider übernimmt Wartung"}, {"text": "Nein", "correct": false, "because": "Wartung ist automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DaaS?', 3, '[{"text": "Datenintegrität", "correct": true, "because": "Zuverlässigkeit entscheidend"}, {"text": "Schnelle Hardware", "correct": false, "because": "Cloud-basiert"}, {"text": "Minimale Kosten", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DaaS ist flexibel. b) Es braucht lokale Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cloud-basiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen hat DaaS?', 5, '[{"text": "Sicherheitsrisiken", "correct": true, "because": "Daten in Cloud"}, {"text": "Compliance", "correct": true, "because": "Regulatorische Anforderungen"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Hauptthema"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DaaS unwichtig?', 3, '[{"text": "Datenqualität", "correct": false, "because": "Entscheidend für Nutzen"}, {"text": "Zugriffskontrolle", "correct": false, "because": "Schützt Daten"}, {"text": "Tastaturlayout", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Benötigt DaaS eine Internetverbindung?', 3, '[{"text": "Ja", "correct": true, "because": "Cloud-Zugriff nötig"}, {"text": "Nein", "correct": false, "because": "Online erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DaaS für kleine Firmen geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Skalierbar für alle Größen"}, {"text": "Nein", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Cloud bei DaaS?', 4, '[{"text": "Datenbereitstellung", "correct": true, "because": "Hostet und liefert Daten"}, {"text": "Grafikverarbeitung", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Hardwaresteuerung", "correct": false, "because": "Nicht relevant"}]');
